    dmRow({ gtin: "03574661799438", title: "Second Ranked Shampoo" }),
  ])
  assert.equal(result.retailer.length, 1)
  assert.equal(result.retailer[0].name, "First Ranked Shampoo")
  assert.equal(result.retailer[0].gtin, "3574661799438")
})

